package server

import "evaltask/internal/limiter"

type Router struct {
	limit  int
	c      *limiter.Counter
	called int
}

func NewRouter(limit int) *Router {
	c := limiter.New(limit)
	return &Router{limit: limit, c: c}
}

func (r *Router) Handle() int {
	if r.c.Allow() {
		r.called++
		return 200
	}
	// Called limit times, return error response
	return 429
}
